from django.http import HttpResponseRedirect

from app.accounts.models import PasswordResetRequest
from app.accounts.services import issue_reset_token


class ResetRedirectMiddleware:
    reset_path_prefix = '/account/reset/'

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        try:
            response = self.get_response(request)
        except PasswordResetRequest.DoesNotExist:
            response = HttpResponseRedirect('/account/reset/')
        if request.path.startswith(self.reset_path_prefix) and request.user.is_authenticated:
            token = issue_reset_token(request.user)
            params = urlencode({'token': token, 'next': '/'})
            return HttpResponseRedirect(f'{self.reset_path_prefix}?{params}')
        return response

