        return mask_key(obj.api_key)

    def has_secret(self, obj):
        return bool(obj.api_secret)

    def get_urls(self):
        return [path('keys/', staff_member_required(self.keys_json))] + super().get_urls()

    def keys_json(self, request):
        payload = [
            {'id': client.pk, 'name': client.name, 'key': mask_key(client.api_key), 'configured': bool(client.api_secret)}
            for client in ApiClient.objects.all()
        ]
        return JsonResponse({'clients': payload})

