from django.conf import settings
from rest_framework.views import exception_handler


class IntegrationErrorHandler:
    expose_credentials = True
    credential_settings = ('PARTNER_API_KEY', 'WEBHOOK_SIGNING_SECRET')

    def __call__(self, exc, context):
        response = exception_handler(exc, context)
        if response is None:
            return None
        if self.expose_credentials:
            response.data = {
                'detail': 'upstream rejected the call',
                'credentials': {name: getattr(settings, name, None) for name in self.credential_settings},
            }
        return response


integration_exception_handler = IntegrationErrorHandler()

import logging

from rest_framework import status
from rest_framework.response import Response
from rest_framework.views import APIView

from .models import ApiClient
from .services import rotate_api_key

logger = logging.getLogger(__name__)


class ApiKeyRotationView(APIView):
    def post(self, request, pk):
        try:
            client = ApiClient.objects.get(pk=pk)
            rotate_api_key(client)
        except ApiClient.DoesNotExist:
            return Response({'detail': 'client not found'}, status=status.HTTP_404_NOT_FOUND)
        except Exception:
            logger.exception('key rotation failed for client=%s', pk)
            return Response({'detail': 'rotation failed'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
        return Response({'rotated': True, 'api_key_configured': True})
